CREATE OR REPLACE FUNCTION public.asset_resolve(p_asset_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare r public.asset_registry_projection%rowtype;c public.asset_candidates%rowtype;
begin select * into r from public.asset_registry_projection where asset_key=p_asset_key;if not found then return jsonb_build_object('ok',false,'fallback',true,'reason','ASSET_KEY_NOT_FOUND','asset_key',p_asset_key);end if;
 select * into c from public.asset_candidates where asset_key=p_asset_key and version=r.active_version and status='ACTIVE';if not found then insert into public.asset_events(asset_key,event_type,version,details)values(r.asset_key,'asset_load_failed',r.active_version,jsonb_build_object('reason','NO_ACTIVE_ASSET'));return jsonb_build_object('ok',false,'fallback',true,'reason','NO_ACTIVE_ASSET','asset_key',r.asset_key,'asset_type',r.asset_type);end if;
 return jsonb_build_object('ok',true,'asset_key',c.asset_key,'asset_type',c.asset_type,'version',c.version,'storage_path',c.storage_path,'ui_anchors',c.ui_anchors,'width_px',c.width_px,'height_px',c.height_px,'mime_type',c.mime_type,'duration_ms',c.duration_ms,'loopable',c.loopable);end$function$

CREATE OR REPLACE FUNCTION public.s1_submit_private_choice(p_room_code text, p_session_token text, p_choice_id text, p_choice_label text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_room_code text := upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_state public.s1_room_state%rowtype;
  v_submitted_count integer;
  v_choice_label text;
begin
  v_player := public.s1_get_player_by_session(v_room_code, p_session_token);

  select *
  into v_state
  from public.s1_room_state
  where room_code = v_room_code
  for update;

  if v_state.phase <> 'collecting' then
    raise exception 'This scene is no longer accepting private choices.';
  end if;

  select choice_label
  into v_choice_label
  from public.s1_scene_choices
  where scene_id = v_state.current_scene
    and choice_id = p_choice_id
    and active = true;

  if not found then
    raise exception 'Invalid choice for the current scene.';
  end if;

  insert into public.s1_player_decisions(room_code, scene_id, player_id, decision_type, choice_id, choice_label)
  values (v_room_code, v_state.current_scene, v_player.player_id, 'private_choice', p_choice_id, v_choice_label);

  insert into public.s1_game_events(room_code, event_type, actor_player_id, details)
  values (v_room_code, 'private_choice_locked', v_player.player_id, jsonb_build_object('scene_id', v_state.current_scene));

  select count(*)
  into v_submitted_count
  from public.s1_player_decisions
  where room_code = v_room_code
    and scene_id = v_state.current_scene
    and decision_type = 'private_choice';

  if v_submitted_count >= 3 then
    update public.s1_room_state
    set phase = 'revealed',
        updated_at = now()
    where room_code = v_room_code;

    insert into public.s1_game_events(room_code, event_type, details)
    values (v_room_code, 'scene_revealed', jsonb_build_object('scene_id', v_state.current_scene));
  end if;

  perform public.s1_touch_room(v_room_code);

  return jsonb_build_object('ok', true, 'submitted_count', v_submitted_count);
exception
  when unique_violation then
    raise exception 'Your first choice for this scene is already locked.';
end;
$function$

CREATE OR REPLACE FUNCTION public.s5_teacher_open_vote(p_room_code text, p_teacher_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare room text:=upper(trim(p_room_code));g public.game_runs%rowtype;s public.s5_run_state%rowtype;sid uuid;
begin perform public.s1_assert_teacher(room,p_teacher_token);g:=public.s2_get_active_run(room);select*into s from public.s5_run_state where run_id=g.run_id;select discussion_session_id into sid from public.s5_rounds where run_id=g.run_id and phase_key=s.phase_key and vote_round=s.vote_round;update public.discussion_sessions set status='voting',phase_deadline=now()+make_interval(secs=>vote_time_limit_sec)where discussion_session_id=sid and status='discussion';if not found then raise exception'Current Sprint 5 discussion is not open.';end if;
insert into public.runtime_events(run_id,room_code,discussion_session_id,event_type,details,scene_id,phase_key,step_key,event_source,validity,behavior_scoring,interaction_id)values(g.run_id,room,sid,'teacher_intervention_s5_vote_opened',jsonb_build_object('vote_round',s.vote_round),null,s.phase_key,null,'teacher_override','valid',false,sid);
return jsonb_build_object('ok',true,'discussion_session_id',sid);end$function$

CREATE OR REPLACE FUNCTION public.s8_export_session(p_room_code text, p_teacher_token text, p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 perform public.s1_assert_teacher(upper(trim(p_room_code)),p_teacher_token);
 if not exists(select 1 from public.game_runs where run_id=p_run_id and room_code=upper(trim(p_room_code)) and status='completed' and export_ready and session_integrity_verified) then raise exception 'Requested session export is not ready.';end if;
 perform set_config('app.s8_export_run_id',p_run_id::text,true);
 return public.s8_export_session(p_room_code,p_teacher_token);
end$function$
